//! 🧪️ The native production receiver preserves its original byte owners and complete Fault through actual finite caller close.
use semio_framework_value::retirement::controlled::ControlledRetirement;
use semio_framework::kernel::Event;
#[cfg(all(target_arch = "wasm32", target_env = "p2"))]
use semio_framework::kernel::RequestOutcome;
use semio_framework_plugin_actor_host::requests;
use semio_framework_plugin_reactor_turn as turn;
use semio_framework_value::ToValue;
#[test]
fn original_completed_full_fault_same_input_zero_work_and_paid_close(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();
 let request=serde_json::to_string(&law["request"]).unwrap();let bytes=serde_json::to_vec(&law["fault"]).unwrap();let pointer=bytes.as_ptr();let request_pointer=request.as_ptr();
 let continuation=requests::ExtensionContinuation{instance:971,response_action:"receive-original".into(),request_json:request,partial:Ok(Vec::new())};
 let mut input=CompletedInput::new(Event::Completed{req:semio_framework::kernel::RequestId(71),result:semio_framework::kernel::RequestOutcome::Err(bytes)},continuation);
 let mut caller=semio_framework_plugin_testing_laws::OriginalFixtureCaller::admit().unwrap();let mut cx=caller.context();let recipient=cx.original_recipient_identity();let before=cx.retained_progress();let fuel=cx.fuel_remaining();let deadline=cx.deadline_us();
 let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cx.with_original_work_loan(0,deadline,|same|input.step(same).map(|_|())));result.unwrap();assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(cx.retained_progress(),before);assert_eq!(cx.fuel_remaining(),fuel);
 let mut fields=None;for turn in 0..semio_framework_plugin_testing_laws::OriginalFixtureCaller::maximum_turns(){let before=cx.retained_progress();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||input.step(&mut cx));let after=cx.retained_progress();assert_eq!((heap.requested_bytes,heap.released_bytes),(after.retained_capacity_bytes-before.retained_capacity_bytes,after.released_bytes-before.released_bytes));fields=result.unwrap();assert_eq!(cx.original_recipient_identity(),recipient);let sources=input.inputs.as_ref().unwrap();assert_eq!(sources.continuation.as_ref().unwrap().request_json.as_ptr(),request_pointer);let Event::Completed{result:semio_framework::kernel::RequestOutcome::Err(bytes),..}=sources.event.as_ref().unwrap()else{panic!()};assert_eq!(bytes.as_ptr(),pointer);if fields.is_some(){break}assert!(turn+1<semio_framework_plugin_testing_laws::OriginalFixtureCaller::maximum_turns())}
 let CompletedResult::Response(fields)=fields.unwrap()else{panic!()};assert_eq!(fields.0.as_deref(),Some("receive-original"));assert_eq!(serde_json::Value::from(fields.1.as_ref().unwrap().clone()),law["expected"]);assert_eq!(serde_json::Value::from(fields.2.as_ref().unwrap().to_value()),law["fault"]);
 let mut fields=ControlledRetirement::new(fields).map_err(|_|()).unwrap();for turn in 0..semio_framework_plugin_testing_laws::OriginalFixtureCaller::maximum_turns(){if fields.terminal_is_empty(){break}let before=cx.retained_progress();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||semio_framework_job::close_original_retained_step(&mut cx,fields.selected_demand(64).unwrap(),|grant|fields.step(grant)));result.unwrap();let after=cx.retained_progress();assert_eq!((heap.requested_bytes,heap.released_bytes),(after.retained_capacity_bytes-before.retained_capacity_bytes,after.released_bytes-before.released_bytes));assert!(turn+1<semio_framework_plugin_testing_laws::OriginalFixtureCaller::maximum_turns())}assert!(fields.terminal_is_empty());drop(fields);
 for turn in 0..semio_framework_plugin_testing_laws::OriginalFixtureCaller::maximum_turns(){let before=cx.retained_progress();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||input.close_step(&mut cx));let after=cx.retained_progress();assert_eq!((heap.requested_bytes,heap.released_bytes),(after.retained_capacity_bytes-before.retained_capacity_bytes,after.released_bytes-before.released_bytes));if result.unwrap(){break}assert!(turn+1<semio_framework_plugin_testing_laws::OriginalFixtureCaller::maximum_turns())}assert!(input.closed);let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(input));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let fuel=cx.fuel_remaining();drop(cx);caller.retire(fuel).unwrap();
}

#[test]
fn original_completed_parked_future_preserves_pages_and_same_source_until_paid_close(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();
 for failed in [false,true]{
  let partial=law["parked"]["partial"].as_str().unwrap().as_bytes().to_vec();let pointer=partial.as_ptr();let tail=if failed{serde_json::to_vec(&law["fault"]).unwrap()}else{law["parked"]["terminal"].as_str().unwrap().as_bytes().to_vec()};let tail_pointer=tail.as_ptr();let result=if failed{semio_framework::kernel::RequestOutcome::Err(tail)}else{semio_framework::kernel::RequestOutcome::Ok(tail)};
  let mut input=CompletedInput::new_request(Event::Completed{req:semio_framework::kernel::RequestId(72),result},partial);let mut caller=semio_framework_plugin_testing_laws::OriginalFixtureCaller::admit().unwrap();let mut cx=caller.context();let before=cx.retained_progress();let fuel=cx.fuel_remaining();let deadline=cx.deadline_us();let(zero,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cx.with_original_work_loan(0,deadline,|same|input.step(same).map(|_|())));zero.unwrap();assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(cx.retained_progress(),before);assert_eq!(cx.fuel_remaining(),fuel);
  let mut received=None;for turn in 0..semio_framework_plugin_testing_laws::OriginalFixtureCaller::maximum_turns(){let sources=input.inputs.as_ref().unwrap();assert_eq!(sources.partial.as_ptr(),pointer);let Event::Completed{result,..}=sources.event.as_ref().unwrap()else{panic!()};let bytes=match result{semio_framework::kernel::RequestOutcome::Ok(bytes)|semio_framework::kernel::RequestOutcome::Err(bytes)=>bytes};assert_eq!(bytes.as_ptr(),tail_pointer);let before=cx.retained_progress();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||input.step(&mut cx));let after=cx.retained_progress();assert_eq!((heap.requested_bytes,heap.released_bytes),(after.retained_capacity_bytes-before.retained_capacity_bytes,after.released_bytes-before.released_bytes));received=result.unwrap();if received.is_some(){break}assert!(turn+1<semio_framework_plugin_testing_laws::OriginalFixtureCaller::maximum_turns())}
  let CompletedResult::Request(result)=received.unwrap()else{panic!()};if failed{assert_eq!(serde_json::Value::from(result.as_ref().unwrap_err().to_value()),law["fault"])}else{assert_eq!(result.as_ref().unwrap(),law["parked"]["expected"].as_str().unwrap().as_bytes())}
  let mut result=ControlledRetirement::new(result).map_err(|_|()).unwrap();for turn in 0..semio_framework_plugin_testing_laws::OriginalFixtureCaller::maximum_turns(){if result.terminal_is_empty(){break}semio_framework_job::close_original_retained_step(&mut cx,result.selected_demand(64).unwrap(),|grant|result.step(grant)).unwrap();assert!(turn+1<semio_framework_plugin_testing_laws::OriginalFixtureCaller::maximum_turns())}assert!(result.terminal_is_empty());drop(result);
  for turn in 0..semio_framework_plugin_testing_laws::OriginalFixtureCaller::maximum_turns(){let before=cx.retained_progress();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||input.close_step(&mut cx));let after=cx.retained_progress();assert_eq!((heap.requested_bytes,heap.released_bytes),(after.retained_capacity_bytes-before.retained_capacity_bytes,after.released_bytes-before.released_bytes));if result.unwrap(){break}assert!(turn+1<semio_framework_plugin_testing_laws::OriginalFixtureCaller::maximum_turns())}assert!(input.closed);let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(input));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let fuel=cx.fuel_remaining();drop(cx);caller.retire(fuel).unwrap();
 }
}
